#include <vector>

class Solution {
public:
    std::vector<int> subarraySum(std::vector<int> arr, int n, long long s) {
        long long current_sum = 0;
        int left = 0;

        for (int right = 0; right < n; ++right) {
            current_sum += arr[right];

            while (current_sum > s && left < right) {
                current_sum -= arr[left++];
            }

            if (current_sum == s) {
                return {left + 1, right + 1}; // 1-based index
            }
        }

        return {-1};
    }
};

class Solution:
    def missingNumber(self, n: int, arr: list[int]) -> int:
        xor_total = 0
        for i in range(1, n + 1):
            xor_total ^= i

        xor_arr = 0
        for num in arr:
            xor_arr ^= num

        return xor_total ^ xor_arr

class Solution {
    public static boolean detectLoop(Node head) {
        if (head == null || head.next == null) return false;

        Node slow = head;
        Node fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;

            if (slow == fast) {
                return true; // Loop detected
            }
        }

        return false;
    }
}

#include <vector>
#include <queue>

class Solution {
public:
    int kthSmallest(int arr[], int l, int r, int k) {
        std::priority_queue<int> maxHeap;

        for (int i = l; i <= r; ++i) {
            maxHeap.push(arr[i]);
            if (maxHeap.size() > static_cast<size_t>(k)) {
                maxHeap.pop();
            }
        }

        return maxHeap.top();
    }
};

export function ispar(x: string): boolean {
  const stack: string[] = [];
  const pairs: Record<string, string> = { ')': '(', '}': '{', ']': '[' };

  for (const ch of x) {
    if (ch === '(' || ch === '{' || ch === '[') {
      stack.push(ch);
    } else if (ch === ')' || ch === '}' || ch === ']') {
      if (stack.length === 0 || stack.pop() !== pairs[ch]) {
        return false;
      }
    }
  }

  return stack.length === 0;
}

class Solution {
public:
    vector<long long> nextLargerElement(vector<long long> arr, int n) {
        vector<long long> result(n);
        stack<long long> st;

        for (int i = n - 1; i >= 0; --i) {
            while (!st.empty() && st.top() <= arr[i]) {
                st.pop();
            }

            result[i] = st.empty() ? -1 : st.top();
            st.push(arr[i]);
        }

        return result;
    }
};

class Solution:
    def isBST(self, root) -> bool:
        prev = float('-inf')

        def inorder(node):
            nonlocal prev
            if not node:
                return True
            if not inorder(node.left):
                return False
            if node.data <= prev:
                return False
            prev = node.data
            return inorder(node.right)

        return inorder(root)

class Solution {
    void solve(int r, int c, vector<vector<int>>& m, int n, string path, vector<string>& ans) {
        if (r == n - 1 && c == n - 1) {
            ans.push_back(path);
            return;
        }

        // Directions: D, L, R, U (lexicographical order)
        int dr[] = {1, 0, 0, -1};
        int dc[] = {0, -1, 1, 0};
        char dir[] = {'D', 'L', 'R', 'U'};

        m[r][c] = 0; // Mark visited

        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && m[nr][nc] == 1) {
                solve(nr, nc, m, n, path + dir[i], ans);
            }
        }

        m[r][c] = 1; // Backtrack
    }

public:
    vector<string> findPath(vector<vector<int>>& m, int n) {
        vector<string> ans;
        if (m[0][0] == 0 || m[n-1][n-1] == 0) return ans;
        solve(0, 0, m, n, "", ans);
        return ans;
    }
};

func minJumps(arr []int, n int) int {
    if n <= 1 {
        return 0
    }
    if arr[0] == 0 {
        return -1
    }

    maxReach := arr[0]
    step := arr[0]
    jump := 1

    for i := 1; i < n; i++ {
        if i == n - 1 {
            return jump
        }

        if i + arr[i] > maxReach {
            maxReach = i + arr[i]
        }

        step--

        if step == 0 {
            jump++
            if i >= maxReach {
                return -1
            }
            step = maxReach - i
        }
    }

    return -1
}

class Solution {
public:
    int lcs(int n, int m, string s1, string s2) {
        vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= m; ++j) {
                if (s1[i - 1] == s2[j - 1]) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        return dp[n][m];
    }
};
